files["nimbus/init.lua"] = [==[
-- Nimbus entry point: load the kernel and the desktop shell, then run the event loop.
local wm = require("kernel.wm")
local apps = require("lib.apps")
local users = require("lib.users")
local theme = require("lib.theme")
local net = require("lib.net")
local display = require("kernel.display")
local notify = require("shell.notify")
local session = require("shell.session")
wm.desktop = require("shell.desktop")
require("shell.taskbar")

-- The API programs see. user, home and prefs are filled in at sign-in; they are for
-- convenience only - permissions are decided inside lib/users, not from these fields.
_G.nimbus = {
  version = "1.0",
  wm = wm, sched = require("kernel.sched"), apps = apps, users = users, session = session, net = net, display = display,
  ui = require("lib.ui"), theme = theme.c, accents = theme.accents, prefs = {},
  fetch = require("lib.fetch"), update = require("lib.update"),
  open = apps.open, notify = notify.push, menu = wm.menu, setPref = session.setPref,
}

-- Ctrl+Shift+Delete opens Task Manager (Esc and Ctrl+Alt+Del never reach the computer).
wm.on(function(e, key)
  local held = wm.held
  if e == "key" and key == keys.delete and (held[keys.leftCtrl] or held[keys.rightCtrl])
    and (held[keys.leftShift] or held[keys.rightShift]) and not wm.modal() then
    apps.launch("taskmgr")
    return true
  end
end)

wm.init(term.current())
display.refresh()
net.start()
users.protect()
if #users.list() == 0 then session.setup() else session.signIn() end

local _, err = pcall(wm.loop) -- the loop only returns by crashing

term.setBackgroundColor(colors.black)
term.setTextColor(colors.white)
term.clear()
term.setCursorPos(1, 1)
printError("Nimbus crashed: " .. tostring(err))
print("Reboot and press 2 for safe mode.")
]==]
files["nimbus/kernel/display.lua"] = [==[
-- Monitors. Advanced monitors become extra desktops ("extend"), copies of the computer's
-- screen ("duplicate", the default) or stay unused ("off"); see Settings > Display.
-- A monitor only reports taps, so taps are turned into clicks. Dragging is replaced by the
-- window menu, right-click by the taskbar's right-click button, and the wheel by list arrows.
local wm = require("kernel.wm")

local display = {}
local mirrors = {} -- duplicate mode: monitor name -> monitor

function display.mode() return settings.get("nimbus.display", "duplicate") end

local function find(name)
  for _, d in ipairs(wm.displays()) do
    if d.name == name then return d end
  end
end

local function touchMode()
  wm.touchMode = #wm.displays() > 1 or next(mirrors) ~= nil -- shows the taskbar's right-click button
  wm.redraw()
end

local function add(name)
  if peripheral.getType(name) ~= "monitor" or display.mode() == "off" or find(name) or mirrors[name] then return end
  local mon = peripheral.wrap(name)
  if not mon.isColor() then return end -- only advanced monitors report taps
  for scale = 5, 0.5, -0.5 do -- the largest text that still leaves room for a 51x19 desktop
    mon.setTextScale(scale)
    local w, h = mon.getSize()
    if w >= 51 and h >= 19 then break end
  end
  mon.setBackgroundColor(colors.black)
  mon.clear()
  if display.mode() == "extend" then wm.addDisplay(name, mon) else mirrors[name] = mon end
  touchMode()
end

local function remove(name)
  local d = find(name)
  if d and d ~= wm.displays()[1] then wm.removeDisplay(d) end
  mirrors[name] = nil
  touchMode()
end

-- Drops every monitor and picks them up again; call after changing the mode.
function display.refresh()
  for name in pairs(mirrors) do remove(name) end
  for i = #wm.displays(), 2, -1 do remove(wm.displays()[i].name) end
  for _, name in ipairs(peripheral.getNames()) do add(name) end
end

function display.setMode(mode)
  settings.set("nimbus.display", mode)
  local saved = settings.save() -- false for standard users: the choice then lasts until restart
  display.refresh()
  return saved
end

-- Names and sizes for the Settings page.
function display.list()
  local out = {}
  for _, d in ipairs(wm.displays()) do out[#out + 1] = { name = d.name, w = d.W, h = d.H } end
  for name, mon in pairs(mirrors) do
    local w, h = mon.getSize()
    out[#out + 1] = { name = name .. " (copy)", w = w, h = h }
  end
  return out
end

wm.on(function(e, name, x, y)
  if e == "monitor_touch" then
    local d = mirrors[name] and wm.displays()[1] or find(name)
    if d then wm.touch(d, x, y) end
    return true
  elseif e == "monitor_resize" then
    local d = find(name)
    if d then wm.resized(d) end
  elseif e == "peripheral" then
    add(name)
  elseif e == "peripheral_detach" then
    remove(name)
  end
end)

-- Duplicate mode: after the computer's screen is drawn, copy it onto each mirror.
wm.afterFrame(function(d)
  if d ~= wm.displays()[1] then return end
  for name, mon in pairs(mirrors) do
    local ok = pcall(function()
      for y = 1, d.H do
        mon.setCursorPos(1, y)
        mon.blit(d.root.getLine(y))
      end
    end)
    if not ok then mirrors[name] = nil end -- unplugged mid-frame
  end
end)

return display
]==]
files["nimbus/kernel/sched.lua"] = [==[
-- Nimbus scheduler: one coroutine per process, each drawing into its own terminal.
local sched = { procs = {}, resumes = 0 }
local nextPid = 1

-- Creates a process but does not run it; the caller resumes it once it is wired up.
function sched.spawn(name, target, fn)
  local p = { pid = nextPid, name = name, term = target, co = coroutine.create(fn), resumes = 0 }
  nextPid = nextPid + 1
  sched.procs[#sched.procs + 1] = p
  return p
end

-- Hands one event to a process if it is waiting for it (same filter rule as multishell).
function sched.resume(p, event, ...)
  if p.dead or coroutine.status(p.co) ~= "suspended" then return end
  if p.filter ~= nil and p.filter ~= event and event ~= "terminate" then return end
  local prevTerm, prevProc = term.redirect(p.term), sched.current
  sched.current = p
  local ok, res = coroutine.resume(p.co, event, ...)
  sched.current = prevProc
  p.term = term.redirect(prevTerm) -- keep whatever the program redirected to
  p.resumes = p.resumes + 1
  sched.resumes = sched.resumes + 1
  if coroutine.status(p.co) == "dead" then
    p.dead = true
    if not ok then p.err = res end
  else
    p.filter = res
  end
end

function sched.broadcast(...)
  for i = 1, #sched.procs do sched.resume(sched.procs[i], ...) end
end

function sched.reap()
  for i = #sched.procs, 1, -1 do
    if sched.procs[i].dead then table.remove(sched.procs, i) end
  end
end

return sched
]==]
files["nimbus/kernel/wm.lua"] = [==[
-- Nimbus window manager: displays, windows, z-order, input routing and compositing.
-- Routing follows rom/programs/advanced/multishell.lua: keyboard goes to the focused
-- process, mouse to the window under the cursor, everything else to every process.
-- The desktop shell plugs in through wm.desktop, wm.taskbar, wm.toast, wm.afterFrame, wm.on
-- and wm.overlay.
--
-- There can be several displays (the computer's screen, then monitors). Exactly one is "in
-- use" at a time - the one being drawn, or the one the current input came from - and
-- wm.size, wm.text, wm.root and the shell hooks all refer to it. That is why the shell's
-- code never mentions displays.
local sched = require("kernel.sched")
local c = require("lib.theme").c

local wm = { wins = {}, held = {}, mouse = { x = 1, y = 1 } }
-- wins is the z-order across all displays: wins[#wins] is on top; minimized windows sit at the bottom
local displays = {} -- [1] is the computer's own screen
local cur, parent, root, W, H -- the display in use, and its fields
local composed -- the display the shell last laid itself out for (taskbar hits, icon positions)
local dirty, cascade = true, 0
local drag, capture, overlay, pending, touching, clockTimer
local listeners, frameHooks = {}, {}
local handle

local BTN = { "#", "_", "+", "x" } -- window menu, minimize, maximize, close; 3 cells each
local BTN_W = #BTN * 3
local MIN_W, MIN_H = BTN_W + 4, 3
local SNAPS = {
  { "Left half", "left" }, { "Right half", "right" },
  { "Top left", "topleft" }, { "Top right", "topright" },
  { "Bottom left", "bottomleft" }, { "Bottom right", "bottomright" },
}
local INPUT = { key = true, key_up = true, char = true, paste = true, terminate = true }

local function use(d) cur, parent, root, W, H = d, d.parent, d.root, d.W, d.H end

function wm.size() return W, H end
function wm.root() return root end
function wm.display() return cur end
function wm.displays() return displays end
function wm.redraw() dirty = true end
function wm.modal() return overlay ~= nil and overlay.modal == true end

-- fn(event, ...) sees every event before it is routed; returning true swallows it.
function wm.on(fn) listeners[#listeners + 1] = fn end

-- fn(display) runs after each display has been drawn.
function wm.afterFrame(fn) frameHooks[#frameHooks + 1] = fn end

function wm.text(x, y, text, bg, fg)
  root.setCursorPos(x, y)
  root.setBackgroundColor(bg)
  root.setTextColor(fg)
  root.write(text)
end

local function layoutRect(name)
  local h = H - 1 -- the bottom row is the taskbar
  local lw, th = math.floor(W / 2), math.floor(h / 2)
  local r = ({
    max = { 1, 1, W, h },
    left = { 1, 1, lw, h },
    right = { lw + 1, 1, W - lw, h },
    topleft = { 1, 1, lw, th },
    topright = { lw + 1, 1, W - lw, th },
    bottomleft = { 1, th + 1, lw, h - th },
    bottomright = { lw + 1, th + 1, W - lw, h - th },
  })[name]
  return r[1], r[2], r[3], r[4]
end

function wm.focused()
  local top = wm.wins[#wm.wins]
  if top and not top.minimized then return top end
end

local function byId(id)
  for _, win in ipairs(wm.wins) do
    if win.id == id then return win end
  end
end

local function winAt(x, y)
  for i = #wm.wins, 1, -1 do
    local win = wm.wins[i]
    if win.display == cur and not win.minimized
      and x >= win.x and x < win.x + win.w and y >= win.y and y < win.y + win.h then
      return win
    end
  end
end

-- User input for one window, in that window's own coordinates.
local function send(win, event, ...)
  win.proc.interacted = true
  sched.resume(win.proc, event, ...)
end

local function setRect(win, x, y, w, h)
  local resized = w ~= win.w or h ~= win.h
  win.x, win.y, win.w, win.h = x, y, w, h
  win.body.reposition(x, y + 1, w, h - 1, win.display.root)
  if resized then sched.resume(win.proc, "term_resize") end
  dirty = true
end

local function restack(win, toBottom)
  for i, other in ipairs(wm.wins) do
    if other == win then table.remove(wm.wins, i) break end
  end
  win.minimized = toBottom
  table.insert(wm.wins, toBottom and 1 or #wm.wins + 1, win)
  dirty = true
end

function wm.focus(win) restack(win, false) end
function wm.minimize(win) restack(win, true) end

function wm.close(win)
  win.proc.dead = true
  dirty = true
end

function wm.resize(win, w, h) setRect(win, win.x, win.y, w, h) end

-- Snap or maximize by layout name; nil puts the window back where it was.
function wm.setLayout(win, name)
  if name then
    win.restore = win.restore or { win.x, win.y, win.w, win.h }
    win.layout = name
    setRect(win, layoutRect(name))
  elseif win.restore then
    local r = win.restore
    win.layout, win.restore = nil, nil
    setRect(win, r[1], r[2], r[3], r[4])
  end
end

-- Moves a window to another display: it keeps its snap layout, or is fitted inside.
function wm.moveTo(win, d)
  local back = cur
  use(d)
  win.display = d
  if win.layout then
    setRect(win, layoutRect(win.layout))
  else
    setRect(win, math.min(win.x, math.max(1, W - 3)), math.min(win.y, H - 1), math.min(win.w, W), math.min(win.h, H - 1))
  end
  use(back)
end

-- target is anything with the term API: the computer's terminal or a monitor.
function wm.addDisplay(name, target)
  local w, h = target.getSize()
  local d = { name = name, parent = target, W = w, H = h, root = window.create(target, 1, 1, w, h, false) }
  displays[#displays + 1] = d
  dirty = true
  return d
end

-- Its windows move to the computer's own screen. The first display can't be removed.
function wm.removeDisplay(d)
  for i = #displays, 2, -1 do
    if displays[i] == d then table.remove(displays, i) end
  end
  if cur == d then use(displays[1]) end
  if composed == d then composed = nil end
  if overlay and overlay.display == d then overlay = nil end
  for _, win in ipairs(wm.wins) do
    if win.display == d then wm.moveTo(win, displays[1]) end
  end
  dirty = true
end

-- Call when a display's terminal changed size.
function wm.resized(d)
  local back = cur
  d.W, d.H = d.parent.getSize()
  d.root.reposition(1, 1, d.W, d.H)
  use(d)
  for _, win in ipairs(wm.wins) do
    if win.display == d and win.layout then setRect(win, layoutRect(win.layout)) end
  end
  use(back)
  dirty = true
end

-- Shows one thing above everything else, on the display in use, until it is dismissed.
-- o = { draw = fn(), click = fn(button, x, y), key = fn(event, arg), scroll = fn(dir) }; click and key
-- return true to stay open. With a key handler the overlay also takes the keyboard;
-- modal = true (sign-in, lock) covers every display and also blocks shortcuts and Ctrl+T. An overlay
-- with raw = fn(event, ...) gets every keyboard and mouse event itself; false from it closes the overlay.
function wm.overlay(o)
  overlay, drag, capture = o, nil, nil
  if o then o.display = cur end
  dirty = true
end

-- items = { { label, fn }, ... }; the next click picks one or dismisses the popup.
function wm.popup(x, y, items, onDismiss)
  local w = 0
  for _, item in ipairs(items) do w = math.max(w, #item[1] + 2) end
  x = math.max(1, math.min(x, W - w + 1))
  y = math.max(1, math.min(y, H - #items))
  wm.overlay({
    draw = function()
      for i, item in ipairs(items) do
        wm.text(x, y + i - 1, (" " .. item[1] .. (" "):rep(w)):sub(1, w), c.card, c.cardText)
      end
    end,
    click = function(_, cx, cy)
      overlay = nil -- before the callback, which may open another popup
      local item = items[cy - y + 1]
      if item and cx >= x and cx < x + w then item[2]() elseif onDismiss then onDismiss() end
    end,
  })
end

-- For programs: a context menu at the last click. The pick comes back to the caller as a
-- "nimbus_menu" event (the index, or nothing if dismissed), so no program code runs in the kernel.
function wm.menu(labels)
  local proc, items = sched.current, {}
  for i, label in ipairs(labels) do
    items[i] = { label, function() sched.resume(proc, "nimbus_menu", i) end }
  end
  wm.popup(wm.mouse.x, wm.mouse.y, items, function() sched.resume(proc, "nimbus_menu") end)
end

local function setTitle(win, title)
  title = title:gsub("%.lua$", "")
  win.title = title == "shell" and "Terminal" or title
  dirty = true
end

-- The multishell API handed to programs, so the stock shell titles its window and
-- `fg`/`bg` open new windows without knowing Nimbus exists.
local ms = {}
wm.multishell = ms

-- New windows open on the display in use: the one the last click or tap came from.
local function open(focus, env, path, ...)
  local args = table.pack(...)
  local n = cascade % 5
  cascade = cascade + 1
  local win = { display = cur, x = 2 + n * 2, y = 2 + n, w = math.min(51, W - 10), h = math.min(20, H - 6) }
  setTitle(win, fs.getName(path))
  win.body = window.create(root, win.x, win.y + 1, win.w, win.h - 1, false)
  win.proc = sched.spawn(win.title, win.body, function()
    os.run(env, path, table.unpack(args, 1, args.n))
    if not win.proc.interacted then -- as in multishell: don't let unseen output vanish
      print("Press any key to close")
      os.pullEvent("key")
    end
  end)
  win.proc.win = win
  win.id = win.proc.pid
  if focus or not wm.focused() then
    table.insert(wm.wins, win)
  else
    table.insert(wm.wins, #wm.wins, win) -- just under the focused window
  end
  sched.resume(win.proc)
  dirty = true
  return win
end

-- Opens a Terminal, or runs a shell command line in a new window.
function wm.run(...)
  return open(true, { shell = shell, multishell = ms }, "rom/programs/shell.lua", ...)
end

function ms.getCurrent() return sched.current and sched.current.pid end
function ms.getCount() return #wm.wins end
function ms.launch(env, path, ...) return open(false, env, path, ...).id end
function ms.getFocus()
  local win = wm.focused()
  return win and win.id
end
function ms.setFocus(id)
  local win = byId(id)
  if win then wm.focus(win) end
  return win ~= nil
end
function ms.getTitle(id)
  local win = byId(id)
  return win and win.title
end
function ms.setTitle(id, title)
  local win = byId(id)
  if win then setTitle(win, title) end
end

local function compose(d)
  use(d)
  composed = d
  root.setVisible(false) -- compose off-screen, then show the frame in one go
  root.setBackgroundColor(c.desk)
  root.clear()
  if wm.desktop then wm.desktop.draw() end
  local top = wm.focused()
  for _, win in ipairs(wm.wins) do
    if win.display == d and not win.minimized then
      local room = win.w - BTN_W
      local title = (" " .. win.title):sub(1, room)
      wm.text(win.x, win.y, title .. (" "):rep(room - #title),
        win == top and c.bar or c.idle, win == top and c.barText or c.idleText)
      for _, b in ipairs(BTN) do
        if b == "x" then root.setBackgroundColor(colors.red) root.setTextColor(colors.white) end
        root.write(" " .. b .. " ")
      end
      -- bodies stay hidden except for this copy, so background windows can't draw over others
      win.body.setVisible(true)
      win.body.setVisible(false)
      if win == top and not win.layout then -- resize grip
        wm.text(win.x + win.w - 1, win.y + win.h - 1, "\127", c.bar, c.barDim)
      end
    end
  end
  wm.text(1, H, (" "):rep(W), c.bar, c.barText)
  if wm.taskbar then wm.taskbar.draw(top) end
  if wm.toast then wm.toast() end
  if overlay and (overlay.modal or overlay.display == d) then overlay.draw() end
  root.setVisible(true)
  for _, fn in ipairs(frameHooks) do fn(d) end

  local blink = false
  if top and top.display == d and not overlay and top.body.getCursorBlink() then
    local cx, cy = top.body.getCursorPos()
    if cx >= 1 and cx <= top.w and cy >= 1 and cy < top.h and top.y + cy < H then
      root.setTextColor(top.body.getTextColor())
      root.setCursorPos(top.x + cx - 1, top.y + cy)
      blink = true
    end
  end
  root.setCursorBlink(blink)
end

-- A monitor can be unplugged mid-frame; its detach event follows and removes the display.
local function composeSafe(d)
  if d == displays[1] then compose(d) else pcall(compose, d) end
end

local function draw()
  dirty = false
  local back = cur
  for _, d in ipairs(displays) do
    if d ~= back then composeSafe(d) end
  end
  composeSafe(back) -- last, so the shell's layout matches the display in use
  use(back)
end

-- Makes d the display in use and gets the shell to lay itself out for it.
local function enter(d)
  use(d)
  if composed ~= d then
    composeSafe(d)
    use(d)
  end
end

-- The window menu: the "#" button, or a tap on the title bar of a touch display (which can't drag).
local function windowMenu(win, x)
  local items = {
    { "Move (then tap)", function() pending = { win = win, mode = "move" } end },
    { "Resize (then tap)", function() pending = { win = win, mode = "resize" } end },
  }
  for _, snap in ipairs(SNAPS) do
    items[#items + 1] = { snap[1], function() wm.setLayout(win, snap[2]) end }
  end
  for _, d in ipairs(displays) do
    if d ~= win.display then items[#items + 1] = { "To " .. d.name, function() wm.moveTo(win, d) end } end
  end
  wm.popup(x, win.y + 1, items)
end

local function titleClick(win, x)
  local b = math.floor((x - (win.x + win.w - BTN_W)) / 3) + 1
  if b < 1 and not touching then
    drag = { win = win, mode = "move", dx = x - win.x }
  elseif b <= 1 then
    windowMenu(win, x)
  elseif b == 2 then
    wm.minimize(win)
  elseif b == 3 then
    wm.setLayout(win, win.layout ~= "max" and "max" or nil)
  else
    wm.close(win)
  end
end

local function click(button, x, y)
  wm.mouse.x, wm.mouse.y = x, y
  if wm.armed then -- the taskbar's right-click button was used just before
    button, wm.armed, dirty = 2, false, true
  end
  if overlay then
    local o = overlay
    if not (o.modal or o.display == cur) then
      overlay = nil -- a click on another display dismisses it
    elseif not o.click(button, x, y) and overlay == o then
      overlay = nil
    end
    dirty = true
    return
  end
  drag, capture = nil, nil
  if pending then -- second step of "Move" or "Resize" from the window menu
    local win, mode = pending.win, pending.mode
    pending = nil
    if win.display == cur and not win.proc.dead then
      wm.focus(win)
      wm.setLayout(win, nil)
      y = math.max(1, math.min(H - 1, y))
      if mode == "move" then
        setRect(win, math.min(x, W - 3), y, win.w, win.h)
      else
        setRect(win, win.x, win.y, math.max(MIN_W, x - win.x + 1), math.max(MIN_H, y - win.y + 1))
      end
    end
    return
  end
  if y == H then
    if wm.taskbar then wm.taskbar.click(button, x) end
    return
  end
  local win = winAt(x, y)
  if not win then
    if wm.desktop then wm.desktop.click(button, x, y) end
    return
  end
  wm.focus(win)
  if y == win.y then
    titleClick(win, x)
  elseif not win.layout and x == win.x + win.w - 1 and y == win.y + win.h - 1 then
    drag = { win = win, mode = "resize" }
  else
    capture = win
    send(win, "mouse_click", button, x - win.x + 1, y - win.y)
  end
end

local function dragTo(x, y)
  local win = drag.win
  y = math.max(1, math.min(H - 1, y))
  if drag.mode == "resize" then
    setRect(win, win.x, win.y, math.max(MIN_W, x - win.x + 1), math.max(MIN_H, y - win.y + 1))
    return
  end
  if win.layout then -- dragging a snapped window pops it back to its old size under the cursor
    drag.dx = math.min(drag.dx, win.restore[3] - BTN_W - 1)
    wm.setLayout(win, nil)
  end
  drag.moved = true
  setRect(win, math.max(4 - win.w, math.min(W - 3, x - drag.dx)), y, win.w, win.h)
end

function handle(e, ...)
  local a, x, y = ... -- forward `...` itself so programs see the event's real argument count
  local mouse = e:sub(1, 6) == "mouse_"
  if mouse and not touching then enter(displays[1]) end -- a real mouse is always on the computer's own screen
  if e == "key" then
    wm.held[a] = true
    -- Ctrl+Tab cycles windows (Alt+Tab never reaches Minecraft)
    if a == keys.tab and (wm.held[keys.leftCtrl] or wm.held[keys.rightCtrl]) and not wm.modal() then
      if wm.wins[1] then wm.focus(wm.wins[1]) end
      return
    end
  elseif e == "key_up" then
    wm.held[a] = nil
  end
  for _, fn in ipairs(listeners) do
    if fn(e, ...) then return end
  end

  if overlay and overlay.raw and (INPUT[e] or mouse) then
    if overlay.raw(e, ...) == false then overlay = nil end
    dirty = true
    return
  end

  if INPUT[e] then
    if overlay and overlay.key and (e ~= "terminate" or overlay.modal) then
      if not overlay.key(e, ...) then overlay = nil end
      dirty = true
    else
      local win = wm.focused()
      if win then send(win, e, ...) end
    end
  elseif e == "mouse_click" then
    click(a, x, y)
  elseif e == "mouse_drag" then
    if drag then dragTo(x, y)
    elseif capture then send(capture, e, a, x - capture.x + 1, y - capture.y) end
  elseif e == "mouse_up" then
    if drag then
      if drag.mode == "move" and drag.moved then -- edge snap, like dragging to a screen edge
        if y <= 1 then wm.setLayout(drag.win, "max")
        elseif x <= 1 then wm.setLayout(drag.win, "left")
        elseif x >= W then wm.setLayout(drag.win, "right") end
      end
      drag = nil
    elseif capture then
      send(capture, e, a, x - capture.x + 1, y - capture.y)
    end
  elseif e == "mouse_scroll" then
    local win = not overlay and winAt(x, y)
    if win and y > win.y and y < H then send(win, e, a, x - win.x + 1, y - win.y) end
    if overlay and overlay.scroll then
      overlay.scroll(a)
      dirty = true
    end
  elseif e == "term_resize" then
    wm.resized(displays[1])
  elseif e == "timer" and a == clockTimer then
    clockTimer = os.startTimer(1)
    dirty = true
  else
    sched.broadcast(e, ...)
  end
end

-- A tap on a touch display: a click and release there. Monitors can't drag, scroll or right-click.
function wm.touch(d, x, y)
  enter(d)
  local button = wm.armed and 2 or 1 -- the taskbar's right-click button
  touching = true
  handle("mouse_click", button, x, y)
  handle("mouse_up", button, x, y)
  touching = false
end

function wm.init(screen)
  use(wm.addDisplay("screen", screen))
  clockTimer = os.startTimer(1)
end

-- Processes one event (or none, to just redraw), then closes dead windows and repaints.
function wm.step(e, ...)
  local before = sched.resumes
  if e then handle(e, ...) end
  for i = #wm.wins, 1, -1 do
    local win = wm.wins[i]
    if win.proc.dead then
      table.remove(wm.wins, i)
      if drag and drag.win == win then drag = nil end
      if capture == win then capture = nil end
      dirty = true
    end
  end
  sched.reap()
  if dirty or sched.resumes ~= before then draw() end
end

function wm.loop()
  wm.step()
  while true do wm.step(os.pullEventRaw()) end -- raw: Ctrl+T reaches the focused app, not the OS
end

return wm
]==]
files["nimbus/lib/apps.lua"] = [==[
-- App registry: every folder in /nimbus/apps with an app.json { name, run, pinned, w, h }.
local wm = require("kernel.wm")

local apps = { list = {}, byId = {} }
local DIR = "/nimbus/apps"

function apps.scan()
  apps.list, apps.byId = {}, {}
  for _, id in ipairs(fs.list(DIR)) do
    local f = fs.open(fs.combine(DIR, id .. "/app.json"), "r")
    local app = f and textutils.unserializeJSON(f.readAll())
    if f then f.close() end
    if app and app.name then -- a broken app.json just hides that app
      app.id = id
      apps.list[#apps.list + 1] = app
      apps.byId[id] = app
    end
  end
end

local function quote(path) return '"' .. path .. '"' end -- shell.run splits on spaces

-- Launches an app (or app id) in a new window; extra arguments are passed as paths.
function apps.launch(app, ...)
  app = apps.byId[app] or app
  local cmd = app.run -- no command means a plain Terminal
  if cmd then
    cmd = cmd:gsub("~", nimbus.home) -- "~" in app.json is the user's home
    for _, arg in ipairs({ ... }) do cmd = cmd .. " " .. quote(arg) end
  end
  local win = cmd and wm.run(cmd) or wm.run()
  win.app, win.title = app.id, app.name
  if app.w and app.h then wm.resize(win, app.w, app.h) end -- app.json may ask for a window size
  return win
end

-- Opens a file or folder with whatever handles it.
function apps.open(path)
  path = "/" .. fs.combine(path, "")
  if fs.isDir(path) then return apps.launch("explorer", path) end
  if path:match("%.lnk$") then -- shortcut: an app id or a shell command line
    local f = fs.open(path, "r")
    local target = f.readAll():gsub("%s+$", "")
    f.close()
    if apps.byId[target] then return apps.launch(target) end
    return wm.run(target)
  elseif path:match("%.lua$") then
    return wm.run(quote(path))
  elseif path:match("%.nfp$") then
    return wm.run("paint", quote(path))
  end
  return wm.run("edit", quote(path))
end

apps.scan()
return apps
]==]
files["nimbus/lib/fetch.lua"] = [==[
-- Reads <base>/<path>, where base is an http(s) URL or a local folder (a disk, a test fixture).
-- Returns the raw bytes, or nil and a reason.
return function(base, path)
  if not base then return nil, "No source set. Run: set nimbus.repo <url>" end
  if base:match("^https?://") then
    if not http then return nil, "HTTP is disabled on this server" end
    local res, err = http.get(base .. "/" .. path, nil, true)
    if not res then return nil, tostring(err) end
    local body = res.readAll() or ""
    res.close()
    return body
  end
  local f = fs.open(fs.combine(base, path), "rb")
  if not f then return nil, "Not found: " .. path end
  local body = f.readAll() or ""
  f.close()
  return body
end
]==]
files["nimbus/lib/net.lua"] = [==[
-- Networking over rednet: discovery, chat, the shared folder and remote desktop.
-- None of it is private or authenticated. Rednet is not encrypted and any computer in range
-- can forge a sender id, so this is for players you trust. The remote-desktop PIN stops
-- accidents, not attackers.
local wm = require("kernel.wm")
local sched = require("kernel.sched")
local notify = require("shell.notify")

local net = { online = false, chat = {}, peers = {} }
local PROTO, SHARED, CHUNK = "nimbus", "/shared", 8192
local INPUTS = { -- the only events a remote viewer may inject
  key = true, key_up = true, char = true, paste = true,
  mouse_click = true, mouse_up = true, mouse_drag = true, mouse_scroll = true,
}
local share -- hosting: { pin, tries, viewer, owner, sent }
local view -- viewing: { host, lines }

local function send(to, msg)
  if to then rednet.send(to, msg, PROTO) else rednet.broadcast(msg, PROTO) end
end

local function openModems()
  net.online = false
  for _, name in ipairs(peripheral.getNames()) do
    if peripheral.getType(name) == "modem" then
      if not rednet.isOpen(name) then rednet.open(name) end
      net.online = true
    end
  end
end

function net.name() return os.getComputerLabel() or "computer" end

-- Asks who is out there; answers trickle into net.peers over the next second.
function net.scan()
  net.peers = {}
  send(nil, { type = "who" })
end

function net.peerList()
  local list = {}
  for _, peer in pairs(net.peers) do list[#list + 1] = peer end
  table.sort(list, function(a, b) return a.id < b.id end)
  return list
end

-- to = computer id, or nil for everyone in range.
function net.say(text, to)
  send(to, { type = "chat", from = net.name(), text = text })
  net.chat[#net.chat + 1] = { from = "me", text = text }
end

-- Remote desktop, host side. Sharing ends when the program that started it closes.
function net.shareStart()
  share = { pin = ("%04d"):format(math.random(0, 9999)), tries = 0, owner = sched.current, sent = {} }
  return share.pin
end

function net.shareStop()
  if share and share.viewer then send(share.viewer, { type = "bye" }) end
  share = nil
end

function net.shareState() return share and { pin = share.pin, viewer = share.viewer } end

-- After the computer's own screen is drawn, send the paired viewer the lines that changed.
wm.afterFrame(function(d)
  if d ~= wm.displays()[1] or not share then return end
  local root, H = d.root, d.H
  if share.owner and share.owner.dead then return net.shareStop() end
  if not share.viewer then return end
  local lines, any = {}, false
  for y = 1, H do
    local text, fg, bg = root.getLine(y)
    local key = text .. fg .. bg
    if share.sent[y] ~= key then share.sent[y], lines[y], any = key, { text, fg, bg }, true end
  end
  if any then send(share.viewer, { type = "frame", lines = lines }) end
end)

-- Remote desktop, viewer side. Call from a program; returns true once paired, or false, reason.
-- The remote screen then covers this one until F12.
function net.connect(id, pin)
  send(id, { type = "pair", pin = pin })
  local timer = os.startTimer(3)
  while true do
    local e, a, msg, proto = os.pullEvent()
    if e == "timer" and a == timer then return false, "No answer" end
    if e == "rednet_message" and a == id and proto == PROTO and type(msg) == "table" then
      if msg.type == "refused" then return false, "Wrong PIN, or it isn't sharing" end
      if msg.type == "paired" then break end
    end
  end
  view = { host = id, lines = {} }
  wm.overlay({
    modal = true,
    draw = function()
      local root = wm.root()
      local W, H = wm.size()
      for y = 1, H do wm.text(1, y, (" "):rep(W), colors.black, colors.white) end
      for y, line in pairs(view.lines) do
        root.setCursorPos(1, y)
        root.blit(line[1], line[2], line[3])
      end
    end,
    raw = function(e, ...)
      if e == "key" and (...) == keys.f12 then
        send(view.host, { type = "bye" })
        view = nil
        return false
      end
      send(view.host, { type = "input", event = { e, ... } })
      return true
    end,
  })
  return true
end

local function validLine(line)
  return type(line) == "table" and type(line[1]) == "string" and type(line[2]) == "string" and type(line[3]) == "string"
    and #line[1] == #line[2] and #line[1] == #line[3] and line[2]:match("^[0-9a-f]*$") and line[3]:match("^[0-9a-f]*$")
end

-- Everything arriving here is untrusted input from another computer.
local function handle(from, msg)
  local kind = msg.type
  if kind == "who" then
    send(from, { type = "here", name = net.name(), user = nimbus.user and nimbus.user.name })
  elseif kind == "here" then
    net.peers[from] = { id = from, name = tostring(msg.name):sub(1, 16), user = msg.user and tostring(msg.user):sub(1, 12) }
  elseif kind == "chat" and type(msg.text) == "string" then
    local who = tostring(msg.from):sub(1, 16) .. "#" .. from
    net.chat[#net.chat + 1] = { from = who, text = msg.text:sub(1, 200) }
    if #net.chat > 100 then table.remove(net.chat, 1) end
    local top = wm.focused()
    if not (top and top.app == "chat") then notify.push("Chat: " .. who, msg.text:sub(1, 40)) end
  elseif kind == "list" then
    local files = {}
    for _, name in ipairs(fs.list(SHARED)) do
      local path = fs.combine(SHARED, name)
      if not fs.isDir(path) then files[#files + 1] = { name = name, size = fs.getSize(path) } end
    end
    send(from, { type = "files", files = files })
  elseif kind == "get" and type(msg.name) == "string" then
    local path = fs.combine(SHARED, msg.name)
    -- only plain files directly inside the shared folder, whatever the name says
    if fs.getDir(path) ~= fs.combine(SHARED, "") or not fs.exists(path) or fs.isDir(path) then
      return send(from, { type = "error", text = "No such file" })
    end
    local f = fs.open(path, "rb")
    local data = f.readAll() or ""
    f.close()
    local parts = math.max(1, math.ceil(#data / CHUNK))
    for i = 1, parts do
      send(from, { type = "chunk", name = msg.name, seq = i, last = i == parts, data = data:sub((i - 1) * CHUNK + 1, i * CHUNK) })
    end
  elseif kind == "pair" then
    if share and not share.viewer and msg.pin == share.pin then
      share.viewer, share.sent = from, {}
      local W, H = wm.size()
      send(from, { type = "paired", w = W, h = H })
      notify.push("Remote Desktop", "Computer #" .. from .. " is in control")
    else
      send(from, { type = "refused" })
      if share and not share.viewer then
        share.tries = share.tries + 1
        if share.tries >= 5 then net.shareStop() end -- a 4-digit PIN doesn't survive guessing
      end
    end
  elseif kind == "input" and share and from == share.viewer and type(msg.event) == "table" and INPUTS[msg.event[1]] then
    os.queueEvent(table.unpack(msg.event, 1, 4))
  elseif kind == "bye" then
    if share and from == share.viewer then net.shareStop() end
    if view and from == view.host then
      view = nil
      wm.overlay(nil)
    end
  elseif kind == "frame" and view and from == view.host and type(msg.lines) == "table" then
    for y, line in pairs(msg.lines) do
      if type(y) == "number" and y >= 1 and y <= 200 and y % 1 == 0 and validLine(line) then view.lines[y] = line end
    end
    wm.redraw()
  end
end

-- Starts the background service: it has no window and shows up in Tasks as "network".
function net.start()
  if not fs.exists(SHARED) then fs.makeDir(SHARED) end
  local proc = sched.spawn("network", window.create(wm.root(), 1, 1, 1, 1, false), function()
    openModems()
    while true do
      local e, from, msg, proto = os.pullEventRaw()
      if e == "peripheral" or e == "peripheral_detach" then
        openModems()
        wm.redraw()
      elseif e == "rednet_message" and proto == PROTO and type(msg) == "table" then
        pcall(handle, from, msg) -- a malformed message must not take the service down
      end
    end
  end)
  sched.resume(proc)
end

return net
]==]
files["nimbus/lib/sha256.lua"] = [==[
-- SHA-256 (FIPS 180-4) on bit32. Returns the digest as 64 hex characters.
local band, bxor, bnot, rshift, rrotate = bit32.band, bit32.bxor, bit32.bnot, bit32.rshift, bit32.rrotate

local K = {
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
}

return function(msg)
  local H = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
  local bits = #msg * 8 -- shortcut: 32-bit length field, fine below 512 MB
  msg = msg .. "\128" .. ("\0"):rep((55 - #msg) % 64) .. "\0\0\0\0"
    .. string.char(rshift(bits, 24), band(rshift(bits, 16), 255), band(rshift(bits, 8), 255), band(bits, 255))

  local w = {}
  for chunk = 1, #msg, 64 do
    for i = 0, 15 do
      local b1, b2, b3, b4 = msg:byte(chunk + i * 4, chunk + i * 4 + 3)
      w[i] = b1 * 0x1000000 + b2 * 0x10000 + b3 * 0x100 + b4
    end
    for i = 16, 63 do
      local x, y = w[i - 15], w[i - 2]
      local s0 = bxor(rrotate(x, 7), rrotate(x, 18), rshift(x, 3))
      local s1 = bxor(rrotate(y, 17), rrotate(y, 19), rshift(y, 10))
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) % 0x100000000
    end

    local a, b, c, d, e, f, g, h = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]
    for i = 0, 63 do
      local s1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
      local ch = bxor(band(e, f), band(bnot(e), g))
      local t1 = (h + s1 + ch + K[i + 1] + w[i]) % 0x100000000
      local s0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
      local maj = bxor(band(a, b), band(a, c), band(b, c))
      h, g, f, e, d, c, b, a = g, f, e, (d + t1) % 0x100000000, c, b, a, (t1 + s0 + maj) % 0x100000000
    end
    local v = { a, b, c, d, e, f, g, h }
    for i = 1, 8 do H[i] = (H[i] + v[i]) % 0x100000000 end
  end

  local out = {}
  for i = 1, 8 do -- two 16-bit halves: %x on values above 2^31 differs between Lua runtimes
    out[i] = ("%04x%04x"):format(math.floor(H[i] / 0x10000), H[i] % 0x10000)
  end
  return table.concat(out)
end
]==]
files["nimbus/lib/theme.lua"] = [==[
-- Theme: every piece of Nimbus draws with these tokens instead of fixed colours.
-- theme.c is one table that is updated in place, so modules can keep a reference to it.
local theme = { c = {}, accents = { "blue", "cyan", "green", "purple", "magenta", "red", "brown" } }

local MODES = {
  dark = {
    bar = "gray", barText = "white", barDim = "lightGray", -- taskbar, active title bar, panels
    card = "lightGray", cardText = "black", cardDim = "gray", -- buttons, menus, toasts
    idle = "lightGray", idleText = "gray", -- inactive title bar
    view = "black", viewText = "white", -- app content
  },
  light = {
    bar = "lightGray", barText = "black", barDim = "gray",
    card = "white", cardText = "black", cardDim = "gray",
    idle = "white", idleText = "lightGray",
    view = "white", viewText = "black",
  },
}

-- desk is the accent: desktop background and selection, always drawn with white text.
function theme.apply(mode, accent)
  for token, name in pairs(MODES[mode] or MODES.dark) do theme.c[token] = colors[name] end
  theme.c.desk = colors.blue
  for _, name in ipairs(theme.accents) do
    if name == accent then theme.c.desk = colors[name] end
  end
end

theme.apply()
return theme
]==]
files["nimbus/lib/ui.lua"] = [==[
-- Small drawing and input helpers for Nimbus apps. Everything draws on the current terminal.
local c = require("lib.theme").c
local ui = {}

-- One full-width row of text.
function ui.row(y, text, bg, fg)
  local w = term.getSize()
  term.setCursorPos(1, y)
  term.setBackgroundColor(bg)
  term.setTextColor(fg)
  term.write((text .. (" "):rep(w)):sub(1, w))
end

-- A row of buttons. Returns hit regions; ui.hit(regions, x) gives the button index.
function ui.buttons(y, labels, bg, fg)
  ui.row(y, "", bg, fg)
  local hits, x = {}, 1
  for i, label in ipairs(labels) do
    term.setCursorPos(x + 1, y)
    term.write(label)
    hits[i] = { x, x + #label + 1 }
    x = x + #label + 1
  end
  return hits
end

function ui.hit(hits, x)
  for i, h in ipairs(hits) do
    if x >= h[1] and x <= h[2] then return i end
  end
end

-- One-line text input on row y; mask ("*") hides what is typed. Returns nil for an empty answer.
function ui.prompt(y, label, default, mask)
  ui.row(y, label, c.card, c.cardText)
  term.setCursorPos(#label + 1, y)
  local text = read(mask, nil, nil, default)
  return text ~= "" and text or nil
end

-- Context menu at the mouse. Returns the picked index, or nil if dismissed.
function ui.menu(labels)
  nimbus.menu(labels)
  local _, i = os.pullEvent("nimbus_menu")
  return i
end

-- A scrollable, selectable list starting at column x, row y1. Without a width it runs
-- to the right edge of the window.
function ui.list(x, y1, width)
  local l = { items = {}, sel = 1, off = 0, rows = 1, w = 1, last = -1 }

  -- Draws rows y1..y2; render(item) returns the row's text.
  function l.draw(y2, render)
    l.w = width or term.getSize() - x + 1
    l.rows = y2 - y1 + 1
    l.sel = math.max(1, math.min(#l.items, l.sel))
    if l.sel <= l.off then l.off = l.sel - 1
    elseif l.sel > l.off + l.rows then l.off = l.sel - l.rows end
    for r = 1, l.rows do
      local i = l.off + r
      local item = l.items[i]
      term.setCursorPos(x, y1 + r - 1)
      local picked = item and i == l.sel
      term.setBackgroundColor(picked and c.desk or c.view)
      term.setTextColor(picked and colors.white or c.viewText)
      term.write(((item and render(item) or "") .. (" "):rep(l.w)):sub(1, l.w))
    end
    -- page arrows at the right edge, for touch screens that have no wheel
    l.up, l.down = l.off > 0, l.off + l.rows < #l.items
    term.setBackgroundColor(c.card)
    term.setTextColor(c.cardText)
    if l.down then
      term.setCursorPos(x + l.w - 1, y2)
      term.write("\31")
    end
    if l.up then
      term.setCursorPos(x + l.w - 1, y1)
      term.write("\30")
    end
  end

  -- Returns "open", item on double-click or Enter; "menu", item-or-nil on right-click;
  -- true when it only used the event.
  function l.event(e, a, mx, my)
    local inside = (e == "mouse_click" or e == "mouse_scroll")
      and mx >= x and mx < x + l.w and my >= y1 and my < y1 + l.rows
    if e == "mouse_click" and inside and mx == x + l.w - 1 and ((my == y1 and l.up) or (my ~= y1 and my == y1 + l.rows - 1 and l.down)) then
      -- an arrow: move the selection just past the view, which scrolls it by a page
      l.sel = my == y1 and math.max(1, l.off - l.rows + 2) or math.min(#l.items, l.off + 2 * l.rows - 1)
      return true
    elseif e == "mouse_click" and inside then
      local i = l.off + my - y1 + 1
      local item = l.items[i]
      if item then
        local double = a == 1 and i == l.sel and os.clock() - l.last < 0.5
        l.sel, l.last = i, double and -1 or os.clock()
        if double then return "open", item end
      end
      if a == 2 then return "menu", item end
      return true
    elseif e == "mouse_scroll" and inside then
      l.sel = l.sel + a
      return true
    elseif e == "key" then
      if a == keys.up then l.sel = l.sel - 1 return true end
      if a == keys.down then l.sel = l.sel + 1 return true end
      if a == keys.enter and l.items[l.sel] then return "open", l.items[l.sel] end
    end
  end

  return l
end

return ui
]==]
files["nimbus/lib/update.lua"] = [==[
-- Updater: compares every file with the SHA-256 in <repo>/build/manifest.json, downloads the
-- ones that differ into a staging folder, and leaves a marker. The bootloader moves them into
-- place on the next boot, so a download that fails half way changes nothing.
-- shortcut: files that were removed upstream are not deleted here; add that when one matters.
local sha256 = require("lib.sha256")
local fetch = require("lib.fetch")

local update = {}
local STAGE, READY = "/.nimbus/update", "/.nimbus/update.ready"

local function managed(path) -- the manifest is downloaded, so its paths are checked before use
  return type(path) == "string" and not path:find("..", 1, true)
    and (path == "startup.lua" or path:match("^nimbus/[%w_%-%./]+$") ~= nil)
end

-- Returns { version, files = { paths that differ }, hashes }, or nil and a reason.
function update.check()
  local repo = settings.get("nimbus.repo")
  local body, err = fetch(repo, "build/manifest.json")
  local manifest = body and textutils.unserializeJSON(body)
  if not manifest or type(manifest.files) ~= "table" then return nil, err or "The manifest is not valid" end
  local changed = {}
  for path, hash in pairs(manifest.files) do
    if not managed(path) then return nil, "The manifest names a file outside Nimbus" end
    local f = fs.open(path, "rb")
    local have = f and sha256(f.readAll() or "")
    if f then f.close() end
    if have ~= hash then changed[#changed + 1] = path end
    sleep(0) -- hashing is slow: yield between files so the computer isn't killed for hogging
  end
  table.sort(changed)
  return { version = manifest.version, files = changed, hashes = manifest.files }
end

-- Downloads what check() found. Returns true, or false and a reason (nothing is staged then).
function update.download(result)
  local repo = settings.get("nimbus.repo")
  local ok, err = pcall(function()
    fs.delete(READY)
    fs.delete(STAGE)
    for _, path in ipairs(result.files) do
      local body, why = fetch(repo, path)
      if not body then error(why, 0) end
      if sha256(body) ~= result.hashes[path] then error("Checksum mismatch: " .. path, 0) end
      local f, denied = fs.open(STAGE .. "/" .. path, "wb")
      if not f then error(denied, 0) end
      f.write(body)
      f.close()
      sleep(0)
    end
    local f = fs.open(READY, "w") -- written last: the bootloader only acts on a complete download
    f.write(textutils.serialize(result.files))
    f.close()
  end)
  if not ok then pcall(fs.delete, STAGE) end
  return ok, err
end

return update
]==]
files["nimbus/lib/users.lua"] = [==[
-- Accounts, the signed-in session, and the file guard for standard users.
-- Passwords are stored as sha256(salt .. password) in /.nimbus/users.db.
-- This is soft security: anyone with the world files, or the debug library, can get past it.
local sha256 = require("lib.sha256")

local users = {}
local DB = ".nimbus/users.db" -- outside /nimbus so the code tree can stay read-only and be replaced by updates
local raw = {} -- the unguarded fs functions; only this module keeps them
for k, v in pairs(fs) do raw[k] = v end

local db, session = {}, nil -- session is a local on purpose: programs can't sign themselves in by editing a table

local function save()
  local f = raw.open(DB, "w")
  f.write(textutils.serialize(db))
  f.close()
end

do
  local f = raw.open(DB, "r")
  if f then
    db = textutils.unserialize(f.readAll()) or {}
    f.close()
  end
end

local function admins()
  local n = 0
  for _, u in pairs(db) do
    if u.admin then n = n + 1 end
  end
  return n
end

-- Before any account exists (first-boot setup) everything is allowed.
local function isAdmin()
  return next(db) == nil or (session ~= nil and db[session] ~= nil and db[session].admin)
end

local function setPassword(u, pw)
  local salt = ""
  for _ = 1, 16 do salt = salt .. ("%x"):format(math.random(0, 15)) end
  u.salt, u.hash = salt, sha256(salt .. pw)
end

function users.list()
  local out = {}
  for name, u in pairs(db) do out[#out + 1] = { name = name, admin = u.admin } end
  table.sort(out, function(a, b) return a.name < b.name end)
  return out
end

function users.current()
  if session and db[session] then return { name = session, admin = db[session].admin } end
end

function users.check(name, pw)
  local u = db[name]
  return u ~= nil and sha256(u.salt .. pw) == u.hash
end

function users.login(name, pw)
  if not users.check(name, pw) then return false end
  session = name
  return true
end

function users.logout() session = nil end

function users.add(name, pw, admin)
  if not isAdmin() then return false, "Admins only" end
  if not name:match("^[%l%d_]+$") or #name > 12 then return false, "Name: 1-12 of a-z, 0-9, _" end
  if db[name] then return false, "That name is taken" end
  db[name] = { admin = admin and true or false }
  setPassword(db[name], pw)
  save()
  return true
end

function users.setPassword(name, pw)
  if not db[name] then return false, "No such user" end
  if not (isAdmin() or name == session) then return false, "Admins only" end
  setPassword(db[name], pw)
  save()
  return true
end

function users.setAdmin(name, admin)
  if not isAdmin() then return false, "Admins only" end
  if not db[name] then return false, "No such user" end
  if db[name].admin and not admin and admins() == 1 then return false, "There must be an admin" end
  db[name].admin = admin and true or false
  save()
  return true
end

-- Removes the account; the home folder is left alone.
function users.remove(name)
  if not isAdmin() then return false, "Admins only" end
  if not db[name] then return false, "No such user" end
  if name == session then return false, "You can't remove yourself" end
  db[name] = nil
  save()
  return true
end

-- True when the signed-in standard user may not write to this path.
local function denied(path)
  local user = session and db[session]
  if not user or user.admin then return false end
  -- lower-case: on a Windows-hosted server /NIMBUS is the same folder as /nimbus
  local top, second = raw.combine(path, ""):lower():match("^([^/]*)/?([^/]*)")
  return top == "nimbus" or top == ".nimbus" or top == ".settings" or top == "startup" or top == "startup.lua"
    or (top == "home" and second ~= session)
end

-- Replaces the global fs write functions, so every program (and io) goes through the guard.
function users.protect()
  fs.open = function(path, mode)
    if mode ~= "r" and mode ~= "rb" and denied(path) then return nil, "/" .. raw.combine(path, "") .. ": Access denied" end
    return raw.open(path, mode)
  end
  for name, checkFirst in pairs({ delete = true, makeDir = true, move = true, copy = false }) do
    fs[name] = function(a, b)
      if (checkFirst and denied(a)) or (b and denied(b)) then error("Access denied", 2) end
      return raw[name](a, b)
    end
  end
  fs.isReadOnly = function(path) return denied(path) or raw.isReadOnly(path) end
end

return users
]==]
files["nimbus/recovery.lua"] = [==[
-- Nimbus safe mode: a plain full-screen menu that needs no window manager.
-- Hold Ctrl+T to drop to the plain CraftOS shell.
local NAME = "Nimbus safe mode"
local hiBg = term.isColor() and colors.blue or colors.white
local hiFg = term.isColor() and colors.white or colors.black

local function paint(bg, fg)
  term.setBackgroundColor(bg)
  term.setTextColor(fg)
end

local function clear()
  paint(colors.black, colors.white)
  term.clear()
  term.setCursorPos(1, 1)
end

local function pause()
  print("\n[press any key]")
  os.pullEvent("key")
end

-- Full-screen list. Returns the chosen index, or nil on Backspace.
local function menu(title, items)
  local sel, top = 1, 1
  local timer = os.startTimer(1) -- redraw every second so the clock ticks
  while true do
    local w, h = term.getSize()
    local rows = h - 2
    if sel < top then top = sel elseif sel >= top + rows then top = sel - rows + 1 end

    clear()
    paint(hiBg, hiFg)
    term.clearLine()
    term.write(" " .. title)
    local clock = textutils.formatTime(os.time(), true)
    term.setCursorPos(w - #clock, 1)
    term.write(clock)
    for i = top, math.min(#items, top + rows - 1) do
      term.setCursorPos(1, i - top + 2)
      if i == sel then paint(hiBg, hiFg) else paint(colors.black, colors.white) end
      term.clearLine()
      term.write(" " .. items[i])
    end
    paint(colors.black, colors.white)
    term.setCursorPos(1, h)
    term.write(" Up/Down  Enter=open  Backspace=back")

    local e, a, _, y = os.pullEvent()
    if e == "key" then
      if a == keys.up and sel > 1 then sel = sel - 1
      elseif a == keys.down and sel < #items then sel = sel + 1
      elseif a == keys.enter and items[sel] then return sel
      elseif a == keys.backspace then return nil end
    elseif e == "mouse_click" then
      local i = y - 2 + top
      if y >= 2 and y < h and items[i] then return i end
    elseif e == "mouse_scroll" then
      sel = math.max(1, math.min(#items, sel + a))
    elseif e == "timer" and a == timer then
      timer = os.startTimer(1)
    end
  end
end

local function launch(wait, ...)
  clear()
  local ok = shell.run(...)
  if wait or not ok then pause() end
end

-- shell.run splits on spaces, so paths are passed quoted
local function quoted(path) return '"/' .. path .. '"' end

local function files()
  local dir = ""
  while true do
    local items = {}
    if dir ~= "" then items[1] = ".." end
    for _, n in ipairs(fs.list(dir)) do
      items[#items + 1] = fs.isDir(fs.combine(dir, n)) and n .. "/" or n
    end
    local i = menu("Files: /" .. dir, items)
    if not i then return end
    local name = items[i]
    local path = fs.combine(dir, name)
    if name == ".." then
      dir = fs.getDir(dir)
    elseif name:sub(-1) == "/" then
      dir = path
    else
      local a = menu(name, { "Run", "Edit", "Delete", "Cancel" })
      if a == 1 then
        launch(true, quoted(path))
      elseif a == 2 then
        launch(false, "edit", quoted(path))
      elseif a == 3 and menu("Delete " .. name .. "?", { "No", "Yes" }) == 2 then
        local ok, err = pcall(fs.delete, path) -- /rom is read-only and throws
        if not ok then clear() print(err) pause() end
      end
    end
  end
end

local actions = {
  { "Shell", function()
    clear()
    print("Type 'exit' to return to " .. NAME)
    shell.run("shell")
  end },
  { "Files", files },
  { "New file", function()
    clear()
    write("File name: ")
    local n = read()
    if n ~= "" then launch(false, "edit", quoted(n)) end
  end },
  { "Lua prompt", function() launch(false, "lua") end },
  { "Reboot", os.reboot },
  { "Shut down", os.shutdown },
}

local labels = {}
for i, a in ipairs(actions) do labels[i] = a[1] end
while true do
  local i = menu(NAME .. "  #" .. os.getComputerID(), labels)
  if i then actions[i][2]() end
end
]==]
files["nimbus/shell/desktop.lua"] = [==[
-- Desktop: wallpaper and the icons for everything in <home>/Desktop.
local wm = require("kernel.wm")
local apps = require("lib.apps")
local c = require("lib.theme").c

local desktop = {}
local icons, selected, lastClick, listed = {}, nil, 0, -1
local walls = {} -- rendered wallpaper, one per display and picture

local function scan()
  listed = os.clock()
  icons = {}
  local dir = nimbus.home and nimbus.home .. "/Desktop"
  if not (dir and fs.isDir(dir)) then return end
  local H = wm.displays()[1].H -- laid out for the computer screen, so the icons fit every display
  local rows = math.max(1, math.floor((H - 2) / 3)) -- icons are 2 rows tall plus a gap
  for i, name in ipairs(fs.list(dir)) do
    local path, ext = fs.combine(dir, name), name:match("%.(%w+)$")
    local icon = {
      path = path, label = name:gsub("%.lnk$", ""),
      x = 2 + math.floor((i - 1) / rows) * 10, y = 2 + ((i - 1) % rows) * 3,
    }
    if fs.isDir(path) then icon.tag, icon.color = "dir", colors.yellow
    elseif ext == "lnk" then icon.tag, icon.color = " " .. name:sub(1, 1):upper() .. " ", colors.lightBlue
    else icon.tag, icon.color = ((ext or "?") .. "   "):sub(1, 3), colors.white end
    icons[i] = icon
  end
end

desktop.refresh = scan

function desktop.draw()
  local W, H = wm.size()
  local path = nimbus.prefs.wallpaper
  local key = path and wm.display().name .. path .. W .. H .. c.desk
  local wall = key and walls[key]
  if key and wall == nil then -- render the image once into its own buffer, not every frame
    walls[key] = false -- false: tried, no usable picture
    local image = fs.exists(path) and paintutils.loadImage(path)
    if image then
      wall = window.create(wm.root(), 1, 1, W, H - 1, false)
      walls[key] = wall
      wall.setBackgroundColor(c.desk)
      wall.clear()
      local old = term.redirect(wall)
      paintutils.drawImage(image, 1, 1)
      term.redirect(old)
    end
  end
  if wall then
    wall.setVisible(true)
    wall.setVisible(false)
  end

  if os.clock() - listed > 1 then scan() end -- picks up files other programs create
  for _, icon in ipairs(icons) do
    local label = icon.label:sub(1, 9)
    wm.text(icon.x + 3, icon.y, icon.tag, icon.color, colors.black)
    local picked = icon.path == selected
    wm.text(icon.x + math.floor((9 - #label) / 2), icon.y + 1, label,
      picked and c.card or c.desk, picked and c.cardText or colors.white)
  end
end

function desktop.click(button, x, y)
  local hit
  for _, icon in ipairs(icons) do
    if x >= icon.x and x < icon.x + 9 and y >= icon.y and y <= icon.y + 1 then hit = icon end
  end
  local double = hit and button == 1 and hit.path == selected and os.clock() - lastClick < 0.5
  selected, lastClick = hit and hit.path, double and 0 or os.clock()
  wm.redraw()
  if double then
    apps.open(hit.path)
  elseif button == 2 and hit then
    wm.popup(x, y, {
      { "Open", function() apps.open(hit.path) end },
      { "Delete", function()
        wm.popup(x, y, {
          { "Keep " .. hit.label, function() end },
          { "Delete " .. hit.label, function() pcall(fs.delete, hit.path) scan() end },
        })
      end },
    })
  elseif button == 2 then
    wm.popup(x, y, {
      { "Open in Files", function() apps.open(nimbus.home .. "/Desktop") end },
      { "Terminal", function() apps.launch("terminal") end },
      { "Refresh", scan },
    })
  end
end

return desktop
]==]
files["nimbus/shell/notify.lua"] = [==[
-- Notifications: a toast above the taskbar, and a notification center behind the tray.
local wm = require("kernel.wm")
local c = require("lib.theme").c

local notify = { list = {}, unread = 0 }
local toast, toastTimer

function notify.push(title, text)
  toast = { title = title, text = text or "" }
  table.insert(notify.list, 1, toast)
  notify.list[21] = nil -- keep the last 20
  notify.unread = notify.unread + 1
  toastTimer = os.startTimer(4)
  wm.redraw()
end

wm.on(function(e, id)
  if e == "timer" and id == toastTimer then
    toast = nil
    wm.redraw()
    return true
  end
end)

local function card(x, y, w, n)
  wm.text(x, y, (" " .. n.title .. (" "):rep(w)):sub(1, w), c.card, c.cardText)
  wm.text(x, y + 1, (" " .. n.text .. (" "):rep(w)):sub(1, w), c.card, c.cardDim)
end

wm.toast = function()
  local W, H = wm.size()
  if toast then card(W - 27, H - 3, 27, toast) end
end

function notify.center()
  notify.unread, toast = 0, nil
  local W, H = wm.size()
  local w = math.min(W, 29)
  local x = W - w + 1
  wm.overlay({
    draw = function()
      for y = 1, H - 1 do wm.text(x, y, (" "):rep(w), c.bar, c.barText) end
      wm.text(x, 1, " Notifications", c.bar, c.barText)
      wm.text(W - 6, 1, " Clear ", c.card, c.cardText)
      for i, n in ipairs(notify.list) do
        if i * 3 + 1 < H then card(x + 1, i * 3, w - 2, n) end
      end
    end,
    click = function(_, cx, cy)
      if cx < x or cy >= H then return false end
      if cy == 1 and cx >= W - 6 then notify.list = {} end
      return true
    end,
  })
end

return notify
]==]
files["nimbus/shell/session.lua"] = [==[
-- Sessions: first-boot setup, sign-in, lock and sign-out screens, and per-user preferences.
local wm = require("kernel.wm")
local users = require("lib.users")
local theme = require("lib.theme")
local notify = require("shell.notify")

local c = theme.c
local session = {}

-- A full-screen form that takes the keyboard and can't be clicked away.
-- tiles: optional list of names to pick from; fields: { { label, secret }, ... }.
-- submit(values, tile) returns an error message to stay open, or nothing when done.
local function form(title, tiles, fields, submit)
  local values, active, tile, msg = {}, 1, 1, ""
  for i = 1, #fields do values[i] = "" end
  local top, tileHits = 1, {}

  wm.overlay({
    modal = true,
    draw = function()
      local W, H = wm.size()
      for y = 1, H do wm.text(1, y, (" "):rep(W), c.desk, colors.white) end
      top = math.max(1, math.floor(H / 2) - 4)
      wm.text(math.max(1, math.floor((W - #title) / 2) + 1), top, title, c.desk, colors.white)
      tileHits = {}
      if tiles then
        local total = 0
        for _, name in ipairs(tiles) do total = total + #name + 3 end
        local x = math.max(1, math.floor((W - total) / 2) + 2)
        for i, name in ipairs(tiles) do
          wm.text(x, top + 2, " " .. name .. " ", i == tile and c.card or c.bar, i == tile and c.cardText or c.barText)
          tileHits[i] = { x, x + #name + 1 }
          x = x + #name + 3
        end
      end
      local x = math.max(1, math.floor((W - 28) / 2) + 1)
      for i, field in ipairs(fields) do
        local shown = field[2] and ("*"):rep(#values[i]) or values[i]
        if i == active then shown = shown .. "_" end
        wm.text(x, top + 3 + i, ("%9s "):format(field[1]), c.desk, colors.white)
        wm.text(x + 10, top + 3 + i, (" " .. shown:sub(-16) .. (" "):rep(18)):sub(1, 18), c.card, c.cardText)
      end
      wm.text(math.max(1, math.floor((W - #msg) / 2) + 1), top + 5 + #fields, msg, c.desk, colors.yellow)
      wm.text(W - 20, H, " Restart ", c.bar, c.barText)
      wm.text(W - 10, H, " Shut down ", c.bar, c.barText)
    end,
    click = function(_, x, y)
      local W, H = wm.size()
      for i, hit in ipairs(tileHits) do
        if y == top + 2 and x >= hit[1] and x <= hit[2] then tile = i end
      end
      if fields[y - top - 3] then active = y - top - 3 end
      if y == H and x >= W - 20 and x <= W - 12 then os.reboot() end
      if y == H and x >= W - 10 then os.shutdown() end
      return true
    end,
    key = function(e, a)
      if e == "char" or e == "paste" then
        values[active] = values[active] .. a
      elseif e == "key" and a == keys.backspace then
        values[active] = values[active]:sub(1, -2)
      elseif e == "key" and a == keys.tab and tiles then
        tile = tile % #tiles + 1
      elseif e == "key" and a == keys.enter then
        if active < #fields then
          active = active + 1
          return true
        end
        msg = submit(values, tiles and tiles[tile])
        if not msg then return false end
        for i, field in ipairs(fields) do
          if field[2] then values[i] = "" end -- retype secrets after an error
        end
        active = 1
      end
      return true
    end,
  })
end

function session.setPref(key, value)
  nimbus.prefs[key] = value
  local f = fs.open(nimbus.home .. "/.prefs", "w")
  f.write(textutils.serialize(nimbus.prefs))
  f.close()
  theme.apply(nimbus.prefs.theme, nimbus.prefs.accent)
  wm.redraw()
end

-- Runs after users.login succeeded: loads the user's desktop.
local function start()
  local user = users.current()
  nimbus.user, nimbus.home = user, "/home/" .. user.name
  local f = fs.open(nimbus.home .. "/.prefs", "r")
  nimbus.prefs = f and textutils.unserialize(f.readAll()) or {}
  if f then f.close() end
  theme.apply(nimbus.prefs.theme, nimbus.prefs.accent)

  local desk = nimbus.home .. "/Desktop"
  if not fs.exists(desk) then -- first sign-in
    fs.makeDir(desk)
    for name, id in pairs({ Files = "explorer", Terminal = "terminal" }) do
      local link = fs.open(desk .. "/" .. name .. ".lnk", "w")
      link.write(id)
      link.close()
    end
    notify.push("Welcome, " .. user.name, "Ctrl+Tab switches windows")
  end
  if wm.desktop then wm.desktop.refresh() end -- show this user's icons at once
end

function session.signIn()
  local names = {}
  for i, u in ipairs(users.list()) do names[i] = u.name end
  form("Sign in to Nimbus", names, { { "Password", true } }, function(values, name)
    if not users.login(name, values[1]) then return "Wrong password" end
    start()
  end)
end

-- Programs keep running behind the lock screen.
function session.lock()
  form("Locked", { nimbus.user.name }, { { "Password", true } }, function(values, name)
    if not users.check(name, values[1]) then return "Wrong password" end
  end)
end

function session.signOut()
  for _, win in ipairs(wm.wins) do wm.close(win) end
  users.logout()
  nimbus.user, nimbus.home, nimbus.prefs = nil, nil, {}
  theme.apply()
  session.signIn()
end

-- First boot: the first account is the admin.
function session.setup()
  local fields = { { "Name" }, { "Password", true }, { "Again", true } }
  form("Welcome to Nimbus - create your account", nil, fields, function(v)
    if v[2] ~= v[3] then return "Passwords don't match" end
    local ok, err = users.add(v[1], v[2], true)
    if not ok then return err end
    settings.set("shell.allow_disk_startup", false) -- a boot disk would otherwise skip the login
    settings.save()
    users.login(v[1], v[2])
    start()
  end)
end

return session
]==]
files["nimbus/shell/start.lua"] = [==[
-- Start menu: search box, app grid, then the session and power buttons.
-- Typing filters the grid; the mouse wheel or the arrows at its right edge scroll it.
local wm = require("kernel.wm")
local apps = require("lib.apps")
local session = require("shell.session")
local c = require("lib.theme").c

local start = {}
local COLS = 3

function start.open()
  local W, H = wm.size()
  local w, h = math.min(W, 44), math.min(H - 1, 13)
  local x, y = math.floor((W - w) / 2) + 1, H - h
  local col, rows = math.floor((w - 2) / COLS), h - 8
  local query, shown, off = "", {}, 0 -- off: grid rows scrolled past
  local buttons = { -- keyed by panel row
    [h - 4] = {
      { nimbus.user.name:sub(1, 8), function() apps.launch("settings") end },
      { "Lock", session.lock }, { "Sign out", session.signOut },
    },
    [h - 2] = { { "Restart", function() os.reboot() end }, { "Shut down", function() os.shutdown() end } },
  }
  local function more() return #shown > (off + rows) * COLS end

  wm.overlay({
    draw = function()
      for row = 0, h - 1 do wm.text(x, y + row, (" "):rep(w), c.bar, c.barText) end
      wm.text(x + 1, y + 1, (" Search: " .. query .. "_" .. (" "):rep(w)):sub(1, w - 2), c.card, c.cardText)
      shown = {}
      for _, app in ipairs(apps.list) do
        if app.name:lower():find(query:lower(), 1, true) then shown[#shown + 1] = app end
      end
      off = math.max(0, math.min(off, math.ceil(#shown / COLS) - rows))
      for i = off * COLS + 1, math.min(#shown, (off + rows) * COLS) do
        local n = i - off * COLS - 1
        local first = i == 1 and query ~= "" -- highlighted: Enter opens this one
        wm.text(x + 1 + (n % COLS) * col, y + 3 + math.floor(n / COLS), (" " .. shown[i].name .. (" "):rep(col)):sub(1, col),
          first and c.desk or c.bar, first and colors.white or c.barText)
      end
      -- scroll arrows, on the blank rows above and below the grid
      if off > 0 then wm.text(x + w - 4, y + 2, " \30 ", c.card, c.cardText) end
      if more() then wm.text(x + w - 4, y + 3 + rows, " \31 ", c.card, c.cardText) end
      for row, list in pairs(buttons) do
        local px = x + 1
        for _, b in ipairs(list) do
          wm.text(px, y + row, " " .. b[1] .. " ", c.card, c.cardText)
          px = px + #b[1] + 3
        end
      end
    end,
    click = function(_, cx, cy)
      if cx < x or cx >= x + w or cy < y or cy >= y + h then return false end
      local row, pos = cy - y, cx - x - 1
      if pos >= w - 5 and (row == 2 or row == 3 + rows) then
        if row == 2 then off = off - 1 elseif more() then off = off + 1 end
        return true
      end
      if buttons[row] then
        local px = 0
        for _, b in ipairs(buttons[row]) do
          if pos >= px and pos < px + #b[1] + 2 then
            b[2]()
            return false -- wm keeps a new overlay (the lock screen) if the button opened one
          end
          px = px + #b[1] + 3
        end
        return true
      end
      local app = row >= 3 and row < 3 + rows and pos >= 0 and pos < col * COLS
        and shown[(off + row - 3) * COLS + math.floor(pos / col) + 1]
      if app then
        apps.launch(app)
        return false
      end
      return true
    end,
    scroll = function(dir) off = off + dir end,
    key = function(e, a)
      if e == "char" then
        query, off = query .. a, 0
      elseif e == "key" and a == keys.backspace then
        query, off = query:sub(1, -2), 0
      elseif e == "key" and a == keys.enter then
        if shown[1] then apps.launch(shown[1]) end
        return false
      end
      return true
    end,
  })
end

return start
]==]
files["nimbus/shell/taskbar.lua"] = [==[
-- Taskbar: Start, pinned apps (merged with their windows), other windows, then the tray.
local wm = require("kernel.wm")
local apps = require("lib.apps")
local notify = require("shell.notify")
local start = require("shell.start")
local c = require("lib.theme").c

local taskbar = {}
local hits, trayX = {}, 0

local function topOf(app) -- the app's highest window, if it has one
  for i = #wm.wins, 1, -1 do
    if wm.wins[i].app == app.id then return wm.wins[i] end
  end
end

function taskbar.draw(top)
  local W, H = wm.size()
  local segs = { { text = " \4 " } } -- Start
  for _, app in ipairs(apps.list) do
    if app.pinned then
      segs[#segs + 1] = { text = " " .. app.name:sub(1, 8) .. " ", app = app, win = topOf(app) }
    end
  end
  local loose = {} -- windows that don't belong to a pinned app
  for _, win in ipairs(wm.wins) do
    local app = apps.byId[win.app]
    if not (app and app.pinned) then loose[#loose + 1] = win end
  end
  table.sort(loose, function(a, b) return a.id < b.id end)

  local tray = (nimbus.net.online and "\18 " or "") -- a modem is attached
    .. (notify.unread > 0 and "\7" .. notify.unread .. " " or "") .. textutils.formatTime(os.time(), true) .. " "
  trayX = W - #tray + 1
  wm.text(trayX, H, tray, c.bar, c.barText)

  local total = 0
  for _, seg in ipairs(segs) do total = total + #seg.text end
  -- window titles shrink (8 characters down to 1) until everything fits left of the tray
  local len = math.max(1, math.min(8, math.floor((trayX - 1 - total) / math.max(1, #loose)) - 2))
  for _, win in ipairs(loose) do
    local seg = { text = " " .. win.title:sub(1, len) .. " ", win = win }
    segs[#segs + 1] = seg
    total = total + #seg.text
  end
  local left = 1
  if wm.touchMode then -- a monitor is in use: taps can't right-click, so this makes the next one a right-click
    wm.text(1, H, " \7\7\7 ", wm.armed and c.card or c.bar, wm.armed and c.cardText or c.barText)
    left = 6
  end
  local x = math.max(left, math.min(math.floor((W - total) / 2) + 1, trayX - total))
  hits = {}
  for _, seg in ipairs(segs) do
    -- shortcut: past about a dozen windows the last ones are dropped; add an overflow menu if that bites
    if x + #seg.text > trayX then break end
    local bg, fg = c.bar, c.barDim -- pinned, not running
    if not seg.app and not seg.win then fg = c.barText
    elseif seg.win and seg.win == top then bg, fg = c.card, c.cardText
    elseif seg.win then fg = c.barText end
    wm.text(x, H, seg.text, bg, fg)
    seg.x1, seg.x2 = x, x + #seg.text - 1
    hits[#hits + 1] = seg
    x = x + #seg.text
  end
end

-- Left click focuses, minimizes or launches; right click on a pinned app opens another window.
function taskbar.click(button, x)
  if x >= trayX then return notify.center() end
  if wm.touchMode and x <= 5 then
    wm.armed = true
    return wm.redraw()
  end
  for _, seg in ipairs(hits) do
    if x >= seg.x1 and x <= seg.x2 then
      if seg.app and (button == 2 or not seg.win) then apps.launch(seg.app)
      elseif not seg.win then start.open()
      elseif seg.win == wm.focused() then wm.minimize(seg.win)
      else wm.focus(seg.win) end
      return
    end
  end
end

wm.taskbar = taskbar
return taskbar
]==]
files["startup.lua"] = [==[
-- Nimbus bootloader. Press 2 within two seconds for safe mode, 3 for plain CraftOS.
-- Once accounts exist, both ask for an admin's password.
local pullEvent = os.pullEvent
os.pullEvent = os.pullEventRaw -- Ctrl+T in here would otherwise drop straight to a shell

term.clear()
term.setCursorPos(1, 1)

-- Install an update the updater finished downloading. Safe to repeat if power is lost half way.
local READY, STAGE = "/.nimbus/update.ready", "/.nimbus/update/"
if fs.exists(READY) then
  local f = fs.open(READY, "r")
  local files = textutils.unserialize(f.readAll()) or {}
  f.close()
  for _, path in ipairs(files) do
    if fs.exists(STAGE .. path) then
      fs.delete(path)
      fs.move(STAGE .. path, path)
    end
  end
  fs.delete(READY)
  fs.delete(STAGE)
  print("Nimbus was updated (" .. #files .. " files).")
end

print("Nimbus  [1] Start  [2] Safe mode  [3] CraftOS")
local pick, timer = "1", os.startTimer(2)
while true do
  local e, a = os.pullEvent()
  if e == "timer" and a == timer then break end
  if e == "char" and (a == "1" or a == "2" or a == "3") then pick = a break end
end

if pick ~= "1" then
  package.path = "/nimbus/?.lua;" .. package.path
  local ok, users = pcall(require, "lib.users")
  if ok and #users.list() > 0 then -- a broken install still lets you in to repair it
    write("Admin name: ")
    local name = read()
    write("Password: ")
    local pw = read("*")
    local admin = false
    for _, u in ipairs(users.list()) do
      if u.name == name and u.admin then admin = true end
    end
    if not (admin and users.check(name, pw)) then
      print("Access denied. Starting Nimbus.")
      sleep(1)
      pick = "1"
    end
  end
end

os.pullEvent = pullEvent
if pick == "1" then
  shell.run("/nimbus/init.lua")
elseif pick == "2" then
  shell.run("/nimbus/recovery.lua")
end
]==]

local free = fs.getFreeSpace("/")
if type(free) == "number" and free < 107813 then
  error("Not enough space: Nimbus needs 105 KB", 0)
end
print("Installing Nimbus 1.0")
for path, body in pairs(files) do
  local f, err = fs.open(path, "wb")
  if not f then error("Could not write " .. path .. ": " .. tostring(err), 0) end
  f.write(body)
  f.close()
end
pcall(fs.delete, shell.getRunningProgram()) -- unpacked: free the space this installer takes
print("Nimbus is installed.")
write("Restart now? (y/n) ")
if read():lower() ~= "n" then os.reboot() end
